"""
Standalone verification harness for the fastapi serialize_response fix.

The environment has no pydantic/starlette, so we exec the REAL functions from
fastapi/routing.py (buggy + fixed), fastapi/encoders.py (jsonable_encoder) and
fastapi/utils.py (create_response_field, create_cloned_field) with a minimal
shim that replicates pydantic 1.5.1 semantics:

  * validate_model looks up input_data[field.alias] (alias required unless
    allow_population_by_field_name)
  * dict(model) -> field-name keys, raw values (nested models stay instances)
  * model.dict(by_alias=..., exclude_unset=...) -> alias keys when by_alias,
    only __fields_set__ when exclude_unset; flags propagate to nested models
  * ModelField.validate replicates SINGLETON / LIST / DICT shapes; validating a
    model instance of a *different* class re-validates via cls(**dict(value))
"""
import ast
import asyncio
import functools
import sys
import typing
from dataclasses import is_dataclass
from enum import Enum
from pathlib import PurePath
from types import GeneratorType
from typing import Any, Callable, Dict, List, Optional, Set, Tuple, Type, Union, cast

# --------------------------------------------------------------------------
# mini pydantic (pydantic 1.5.1 semantics)
# --------------------------------------------------------------------------
SHAPE_SINGLETON = 1
SHAPE_LIST = 2
SHAPE_DICT = 8
_missing = object()


class ErrorWrapper:
    def __init__(self, exc, loc):
        self.exc = exc
        self.loc = loc

    def __repr__(self):
        return f"ErrorWrapper(exc={self.exc!r}, loc={self.loc!r})"


class MissingError(ValueError):
    msg_template = "field required"


class ValidationError(Exception):
    def __init__(self, errors, model):
        self.raw_errors = errors
        self.model = model
        super().__init__(repr(errors))


class BaseConfig:
    allow_population_by_field_name = False
    orm_mode = False
    extra = "ignore"
    validate_all = False
    copy_on_model_validation = False


class FieldInfo:
    def __init__(self, default=None, **kwargs):
        self.default = default
        self.alias = kwargs.get("alias")
        self.extra = kwargs


class UndefinedType:
    pass


class Validator:
    pass


def lenient_issubclass(x, cls):
    return isinstance(x, type) and issubclass(x, cls)


def get_origin_safe(t):
    return typing.get_origin(t)


def get_args_safe(t):
    return typing.get_args(t)


class ModelField:
    def __init__(
        self,
        *,
        name,
        type_,
        class_validators,
        model_config,
        default=None,
        required=False,
        alias=None,
        field_info=None,
    ):
        self.name = name
        self.has_alias = bool(alias) or bool(getattr(field_info, "alias", None))
        self.alias = alias or getattr(field_info, "alias", None) or name
        self.alt_alias = self.has_alias and self.alias != self.name
        self.type_ = type_
        self.class_validators = class_validators or {}
        self.default = default
        self.required = required
        self.model_config = model_config
        self.field_info = field_info or FieldInfo(default)
        self.allow_none = default is None or not required
        self.validate_always = False
        self.sub_fields = None
        self.key_field = None
        self.validators = []
        self.pre_validators = None
        self.post_validators = None
        self.parse_json = False
        self.shape = SHAPE_SINGLETON
        self._type_analysis()
        self.populate_validators()

    def _make_sub(self, name, type_):
        return ModelField(
            name=name,
            type_=type_,
            class_validators=self.class_validators,
            model_config=self.model_config,
        )

    def _type_analysis(self):
        origin = get_origin_safe(self.type_)
        if origin is list or self.type_ is list:
            self.shape = SHAPE_LIST
            args = get_args_safe(self.type_)
            self.type_ = args[0] if args else Any
            self.sub_fields = [self._make_sub(f"{self.name}_item", self.type_)]
        elif origin is dict or self.type_ is dict:
            self.shape = SHAPE_DICT
            args = get_args_safe(self.type_)
            self.key_field = self._make_sub(f"{self.name}_key", args[0] if args else str)
            self.type_ = args[1] if len(args) > 1 else Any
            self.sub_fields = [self._make_sub(f"{self.name}_val", self.type_)]
        elif lenient_issubclass(self.type_, BaseModel):
            self.shape = SHAPE_SINGLETON

    def populate_validators(self):
        # real pydantic builds self.validators here; our validate() dispatches
        # on type_ directly, so nothing to do.
        return None

    def get_default(self):
        import copy

        return copy.deepcopy(self.default)

    def _validate_value(self, v, values, loc, cls):
        """Validate a single (unshaped) value against self.type_."""
        t = self.type_
        if v is None:
            return None, None
        if lenient_issubclass(t, BaseModel):
            try:
                return t.validate(v), None
            except ValidationError as e:
                return None, e.raw_errors
        if t is Any or t is None:
            return v, None
        try:
            if isinstance(v, t):
                return v, None
        except TypeError:
            return v, None
        try:
            return t(v), None
        except Exception as e:
            return None, ErrorWrapper(e, loc)

    def validate(self, value, values=None, *, loc=(), cls=None):
        values = values or {}
        if self.shape == SHAPE_SINGLETON:
            return self._validate_value(value, values, loc, cls)
        if self.shape == SHAPE_LIST:
            if not isinstance(value, (list, tuple, set)):
                return None, ErrorWrapper(ValueError("value is not a valid list"), loc)
            result, errors = [], []
            for i, item in enumerate(value):
                v_, e_ = self.sub_fields[0].validate(item, values, loc=loc + (i,), cls=cls)
                if e_ is None:
                    result.append(v_)
                elif isinstance(e_, list):
                    errors.extend(e_)
                else:
                    errors.append(e_)
            return (result, errors or None)
        if self.shape == SHAPE_DICT:
            if not isinstance(value, dict):
                return None, ErrorWrapper(ValueError("value is not a valid dict"), loc)
            result, errors = {}, []
            for k, item in value.items():
                k_, ke_ = self.key_field.validate(k, values, loc=loc + (k,), cls=cls)
                if ke_:
                    errors.append(ke_ if isinstance(ke_, ErrorWrapper) else ke_)
                    continue
                v_, e_ = self.sub_fields[0].validate(item, values, loc=loc + (k,), cls=cls)
                if e_ is None:
                    result[k_] = v_
                elif isinstance(e_, list):
                    errors.extend(e_)
                else:
                    errors.append(e_)
            return (result, errors or None)
        raise AssertionError("bad shape")


def validate_model(model, input_data):
    """pydantic 1.5.1 validate_model: always looks up field.alias; falls back to
    field.name only when allow_population_by_field_name and field.alt_alias."""
    values, errors, fields_set = {}, [], set()
    config = model.__config__
    for name, field in model.__fields__.items():
        value = input_data.get(field.alias, _missing)
        if value is _missing and config.allow_population_by_field_name and field.alt_alias:
            value = input_data.get(field.name, _missing)
        if value is _missing:
            if field.required:
                errors.append(ErrorWrapper(MissingError(), loc=field.alias))
                continue
            value = field.get_default()
            values[name] = value
            continue
        fields_set.add(name)
        v_, e_ = field.validate(value, values, loc=field.alias)
        if isinstance(e_, ErrorWrapper):
            errors.append(e_)
        elif isinstance(e_, list):
            errors.extend(e_)
        else:
            values[name] = v_
    if errors:
        return {}, fields_set, ValidationError(errors, model)
    return values, fields_set, None


class BaseModel:
    __fields__ = {}
    __config__ = BaseConfig

    def __init__(self, **data):
        values, fields_set, error = validate_model(self.__class__, data)
        if error:
            raise error
        object.__setattr__(self, "__dict__", values)
        object.__setattr__(self, "__fields_set__", fields_set)

    @classmethod
    def validate(cls, value):
        # pydantic 1.5.1 BaseModel.validate
        if isinstance(value, cls):
            return value
        elif isinstance(value, dict):
            return cls(**value)
        elif cls.__config__.orm_mode:
            raise AssertionError("orm_mode not supported in shim")
        else:
            return cls(**dict(value))

    def __iter__(self):
        # dict(model) -> field-name keys, raw values (to_dict=False)
        yield from self._iter(to_dict=False)

    def _get_key(self, field_name, by_alias):
        field = self.__fields__[field_name]
        return field.alias if by_alias else field.name

    def _iter(self, to_dict, by_alias=False, exclude_unset=False):
        allowed = self.__fields_set__ if exclude_unset else set(self.__dict__)
        for k, v in self.__dict__.items():
            if k in allowed:
                yield k, self._get_value(v, to_dict, by_alias, exclude_unset)

    def _get_value(self, v, to_dict, by_alias, exclude_unset):
        if isinstance(v, BaseModel):
            if to_dict:
                return v.dict(by_alias=by_alias, exclude_unset=exclude_unset)
            return v
        if isinstance(v, list):
            return [self._get_value(i, to_dict, by_alias, exclude_unset) for i in v]
        if isinstance(v, dict):
            return {
                k: self._get_value(i, to_dict, by_alias, exclude_unset)
                for k, i in v.items()
            }
        return v

    def dict(self, *, include=None, exclude=None, by_alias=False, exclude_unset=False,
             exclude_defaults=False, exclude_none=False, skip_defaults=False):
        out = {}
        for k, v in self._iter(
            to_dict=True, by_alias=by_alias,
            exclude_unset=bool(exclude_unset or skip_defaults),
        ):
            out[self._get_key(k, by_alias)] = v
        return out

    def __repr__(self):
        return f"{self.__class__.__name__}({self.__dict__})"


def create_model(name, __base__=None):
    cls = type(name, (__base__ or BaseModel,), {})
    cls.__fields__ = dict((__base__ or BaseModel).__fields__)
    cls.__config__ = (__base__ or BaseModel).__config__
    return cls


