def build_serialize(path):
    """Exec serialize_response (+ _prepare_response_content if present) from a
    routing.py file against the shims."""
    ns = {
        "run_in_threadpool": run_in_threadpool, "ErrorWrapper": ErrorWrapper,
        "ValidationError": ValidationError, "jsonable_encoder": jsonable_encoder,
        "BaseModel": BaseModel, "PYDANTIC_1": PYDANTIC_1, "ModelField": ModelField,
        "SetIntStr": SetIntStr, "DictIntStrAny": DictIntStrAny,
        "Any": Any, "Callable": Callable, "Dict": Dict, "List": List,
        "Optional": Optional, "Sequence": typing.Sequence, "Set": Set, "Type": Type,
        "Union": Union,
    }
    for name, src in extract_funcs(
        path, {"serialize_response", "_prepare_response_content"}
    ).items():
        exec(src, ns)
    return ns


